from bisect import bisect_right

def lis(a):
	n = len(a)
	INF = float('inf')
	d = [INF] * (n + 1)
	d[0] = -INF
	for i in range(n):
		j = bisect_right(d, a[i])
		if d[j - 1] <= a[i] < d[j]:
			d[j] = a[i]
	ans = 0
	for i in range(n + 1):
		if d[i] < INF:
			ans = i
	return ans
for _ in range(int(input())):
	(n, k) = map(int, input().split())
	a = sorted(map(int, input().split()))
	c = a[:k]
	for i in range(k, n):
		for j in reversed(range(len(c))):
			b = c[:j] + [a[i]] + c[j:]
			if lis(b) == k:
				c = b
				break
	print(-1) if lis(c) != k or sorted(c) != a else print(*c)
